<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from 'vue'
import { ImagePlus, LoaderCircle, X } from 'lucide-vue-next'
import Modal from './Modal.vue'
import HistoryPanel from './HistoryPanel.vue'
import DraftNotice from './DraftNotice.vue'
import ConflictNotice from './ConflictNotice.vue'
import { useDraft,useConflict } from '../drafts'
import { api, dateTimeLabel, dateTimeLocal, isArchived, messageOf, notify, pickFields, recordTypes, softDelete, ui } from '../api'
import type { Attachment, RecordEntry } from '../types'
const props=defineProps<{open:boolean;projectId?:string;record?:RecordEntry}>();const emit=defineEmits<{close:[];saved:[]}>()
const initial=()=>({project_id:props.projectId||'',type:'note',title:'',content:'',location:'',tags:'',reminder_local:'',attachments:[] as Attachment[]})
const form=reactive(initial()),saving=ref(false),loadingRecord=ref(false),uploading=ref(0),error=ref(''),fileInput=ref<HTMLInputElement>(),contentInput=ref<HTMLTextAreaElement>(),editing=ref<RecordEntry>(),knownTags=ref<string[]>([]),completion=ref(''),completionType=ref('')
const draft=useDraft(()=>`records:${editing.value?.id||'new'}`,form,()=>props.open,()=>editing.value?.version),conflict=useConflict()
const readonly=computed(()=>isArchived(form.project_id));const writableProjects=computed(()=>ui.projects.filter(p=>p.status!=='archived'))
const completions=computed(()=>completionType.value==='@'?writableProjects.value.filter(p=>p.name.includes(completion.value)||p.code.includes(completion.value)).slice(0,6).map(p=>({label:p.name,value:p.name,id:p.id})):completionType.value==='#'?knownTags.value.filter(t=>t.includes(completion.value)).slice(0,8).map(t=>({label:t,value:t,id:''})):[])
function assign(record:RecordEntry){Object.assign(form,pickFields(record,initial()),{tags:(record.tags||[]).join(' '),attachments:record.attachments||[],reminder_local:dateTimeLocal(record.reminder_due_at||'')})}
watch(()=>props.open,async open=>{if(!open)return;error.value='';conflict.clear();editing.value=props.record;props.record?assign(props.record):Object.assign(form,initial());if(props.record){loadingRecord.value=true;try{editing.value=await api<RecordEntry>(`/api/records/${props.record.id}`);assign(editing.value)}catch(e){error.value=messageOf(e)}finally{loadingRecord.value=false}}await draft.reset();void loadTags('')})
let tagRequest=0
async function loadTags(q:string){const request=++tagRequest;try{const result=await api<{items:string[];total:number}>(`/api/tags?q=${encodeURIComponent(q)}`);if(request===tagRequest)knownTags.value=result.items}catch{if(request===tagRequest)knownTags.value=[]}}
async function upload(files:File[]){for(const file of files){if(form.attachments.length+uploading.value>=9){error.value='每条记录最多添加 9 张图片';continue}if(!['image/png','image/jpeg','image/gif'].includes(file.type)){error.value='请选择 PNG、JPEG 或 GIF 图片';continue}if(file.size>20*1024*1024){error.value='每张图片不得超过 20 MB';continue}uploading.value++;try{const data=new FormData();data.set('file',file);form.attachments.push(await api<Attachment>('/api/attachments',{method:'POST',body:data}))}catch(e){error.value=messageOf(e)}finally{uploading.value--}}}
function choose(event:Event){const target=event.target as HTMLInputElement;if(target.files)void upload(Array.from(target.files));target.value=''}
function paste(event:ClipboardEvent){if(readonly.value)return;const files=Array.from(event.clipboardData?.files||[]).filter(file=>file.type.startsWith('image/'));if(files.length){event.preventDefault();void upload(files)}}
function updateCompletion(){const input=contentInput.value;if(!input)return;const before=form.content.slice(0,input.selectionStart);const match=before.match(/(?:^|\s)([@#])([^\s@#]*)$/);completionType.value=match?.[1]||'';completion.value=match?.[2]||'';if(completionType.value==='#')void loadTags(completion.value)}
function complete(value:{value:string;id:string}){const input=contentInput.value;if(!input)return;const caret=input.selectionStart;const before=form.content.slice(0,caret);const match=before.match(/(?:^|\s)([@#])([^\s@#]*)$/);if(!match)return;form.content=before.slice(0,before.length-match[2]!.length)+value.value+' '+form.content.slice(caret);if(completionType.value==='@')form.project_id=value.id;else if(!form.tags.split(/[,，\s]+/).includes(value.value))form.tags=(form.tags+' '+value.value).trim();completionType.value='';nextTick(()=>input.focus())}
function keydown(event:KeyboardEvent){if(event.key==='Escape'&&completionType.value){event.preventDefault();event.stopPropagation();completionType.value='';return}if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(completions.value.length)complete(completions.value[0]!);else void save()}}
function requestClose(){if(saving.value||uploading.value)return;if(draft.canLeave())emit('close')}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as RecordEntry;if(!remote)return;draft.persist();editing.value=remote;assign(remote);conflict.clear();await draft.reset();error.value='已载入新内容。原修改仍在浏览器草稿中，可按需恢复比较。'}
async function remove(){if(!editing.value)return;try{if(await softDelete('records',editing.value,form.title||'现场记录')){draft.discard();emit('saved');emit('close')}}catch(e){error.value=messageOf(e)}}
async function save(){if(saving.value||loadingRecord.value||uploading.value||readonly.value)return;if(!form.content.trim()&&!form.title.trim()&&!form.attachments.length){error.value='写下记录内容或添加图片后再保存';return}saving.value=true;error.value='';const {reminder_local,...fields}=form;const reminderChanged=reminder_local!==dateTimeLocal(editing.value?.reminder_due_at||'');const payload={...fields,...((reminder_local&&(!editing.value||reminderChanged))?{reminder_due_at:new Date(reminder_local).toISOString()}:editing.value&&reminderChanged?{reminder_due_at:null}:{}),tags:form.tags.split(/[,，\s]+/).map(t=>t.replace(/^#/,'' )).filter(Boolean),...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<RecordEntry>(editing.value?`/api/records/${editing.value.id}`:'/api/records',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});draft.discard();notify(saved.reminder?`记录已保存，提醒时间：${dateTimeLabel(saved.reminder.due_at)}${saved.reminder_parse_hint?'；'+saved.reminder_parse_hint:''}`:saved.reminder_parse_hint?`记录已保存；${saved.reminder_parse_hint}`:'记录已保存');emit('saved');emit('close')}catch(e){error.value=messageOf(e);if(editing.value)await conflict.capture(e,`/api/records/${editing.value.id}`,payload)}finally{saving.value=false}}
</script>
<template><Modal :open="open" :title="editing?'现场记录详情':'记下现场的事'" wide @close="requestClose"><form class="modal-body" @submit.prevent="save"><DraftNotice :value="draft.available.value" :error="draft.storageError.value" :values="draft.values.value" @select="draft.select" :recovery="draft.recovery.value" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @restore="draft.restore" @discard="draft.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="draft.persist();conflict.clear()" @reload="reloadConflict"/><fieldset :disabled="readonly||saving||loadingRecord"><div class="form-row"><label>关联项目<select v-model="form.project_id"><option value="">未归类，稍后整理</option><option v-for="p in ui.projects.filter(p=>p.status!=='archived'||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>记录类型<select v-model="form.type"><option v-for="(name,key) in recordTypes" :key="key" :value="key">{{name}}</option></select></label></div><label>标题 <span class="muted">选填</span><input v-model="form.title" maxlength="200" placeholder="用一句话概括"/></label><label>记录内容<textarea ref="contentInput" v-model="form.content" autofocus rows="7" placeholder="发生了什么？有什么结论或需要跟进的事？输入 @ 关联项目，# 选择标签" @paste="paste" @keydown="keydown" @input="updateCompletion" @click="updateCompletion"/></label><div v-if="completions.length" class="completion-list" aria-label="补全建议"><button v-for="item in completions" :key="item.value" type="button" @click="complete(item)">{{completionType}}{{item.label}}</button></div><p class="input-hint">Enter 保存，Shift + Enter 换行；支持粘贴截图，最多 9 张，每张 20 MB。</p><div class="upload-strip"><button type="button" class="button subtle small" :disabled="uploading>0||form.attachments.length>=9" @click="fileInput?.click()"><LoaderCircle v-if="uploading" class="spin" :size="16"/><ImagePlus v-else :size="16"/>{{uploading?'正在上传…':'添加图片'}}</button><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/gif" multiple hidden @change="choose"/><div v-for="(a,index) in form.attachments" :key="a.id" class="uploaded-image"><img :src="a.thumb_url||a.url||`/api/attachments/${a.id}`" :alt="a.filename"/><button type="button" :aria-label="`移除图片 ${a.filename}`" @click="form.attachments.splice(index,1)"><X :size="12"/></button></div></div><div class="form-row"><label>位置 <span class="muted">选填</span><input v-model="form.location" placeholder="例如：主厂房二层" maxlength="200"/></label><label>标签 <span class="muted">空格或逗号分隔</span><input v-model="form.tags" list="record-tags" @input="loadTags(form.tags.split(/[,，\s]+/).pop()||'')" placeholder="验收 设备安全"/><datalist id="record-tags"><option v-for="tag in knownTags" :key="tag" :value="tag"/></datalist></label></div><label>一次提醒时间 <span class="muted">选填，本地时间</span><input v-model="form.reminder_local" type="datetime-local" :disabled="!!editing?.reminder?.done_at"/><span v-if="editing?.reminder?.done_at" class="input-hint">关联提醒已完成。若需再次提醒，请在提醒页新建，保留原完成记录。</span></label><p class="input-hint reminder-syntax">也可在新记录中单独输入 !今天、!明天、!周五 或 !2026-12-01，后接 HH:mm。未写时间默认本地 09:00；今天已过的时间会调整为当前后 1 分钟。指定上方时间时优先使用该时间。提醒在工作台显示，不触发系统通知。</p></fieldset><HistoryPanel v-if="editing" kind="records" :id="editing.id" :revision="editing.version"/><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-footer"><span class="muted">{{readonly?'项目已归档，只读':'浏览器草稿与数据库保存相互独立'}}</span><button v-if="editing&&!readonly" type="button" class="button subtle small" @click="remove">移入回收站</button><button v-if="!readonly" type="submit" class="button primary" :disabled="saving||loadingRecord||uploading>0">{{saving?'正在保存…':'保存记录'}}</button></div></form></Modal></template>
